// Initialize
window.addEventListener("DOMContentLoaded", () => {
  initAudioContext();
  loadPresets();
  setupEventListeners();
  updateModelSpecs(activeModel);
});

function initAudioContext() {
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (AudioCtx && !audioContext) {
    audioContext = new AudioCtx({ sampleRate: 44100 });
  }
}

function updateModelSpecs(modelKey) {
  const spec = MODEL_SPECS[modelKey] || MODEL_SPECS.multifeature;
  specModelName.textContent = spec.name;
  specParams.textContent = spec.params;
  specAcc.textContent = spec.acc;
  specLatency.textContent = spec.latency;
  activeModelBadge.textContent = spec.badge;
}

// Model Selector Event
modelSelect.addEventListener("change", (e) => {
  activeModel = e.target.value;
  updateModelSpecs(activeModel);
  if (activePreset) {
    runPresetInference(activePreset.filename, activeModel);
  } else if (currentAudioBlob) {
    runInference(currentAudioBlob, activeModel);
  }
});

// 50-Preset State
let allPresetsData = [];
let currentFilterGroup = "All";
let currentSearchQuery = "";

const presetSearchInput = document.getElementById("presetSearchInput");
const filterChips = document.querySelectorAll(".filter-chip");

// Load Presets from Backend API (with static fallback)
async function loadPresets() {
  try {
    let res = await fetch("/api/samples");
    if (!res.ok) {
      res = await fetch("/data/samples.json");
    }
    allPresetsData = await res.json();
    renderFilteredPresets();

    // Auto-select first preset
    if (allPresetsData.length > 0) {
      const firstCard = presetGrid.querySelector(".preset-card");
      selectPreset(allPresetsData[0], firstCard);
    }

    // Setup filter listeners
    filterChips.forEach(chip => {
      chip.addEventListener("click", () => {
        filterChips.forEach(c => c.classList.remove("active"));
        chip.classList.add("active");
        currentFilterGroup = chip.dataset.group;
        renderFilteredPresets();
      });
    });

    // Setup search listener
    if (presetSearchInput) {
      presetSearchInput.addEventListener("input", (e) => {
        currentSearchQuery = e.target.value.toLowerCase().trim();
        renderFilteredPresets();
      });
    }
  } catch (err) {
    console.error("Failed loading presets from API, trying static data fallback:", err);
    try {
      const fallbackRes = await fetch("/data/samples.json");
      allPresetsData = await fallbackRes.json();
      renderFilteredPresets();
      if (allPresetsData.length > 0) {
        const firstCard = presetGrid.querySelector(".preset-card");
        selectPreset(allPresetsData[0], firstCard);
      }
    } catch (e2) {
      console.error("Critical: Could not load presets:", e2);
    }
  }
}

// Render Presets matching Group Filter and Search Query
function renderFilteredPresets() {
  presetGrid.innerHTML = "";

  const filtered = allPresetsData.filter(p => {
    const matchesGroup = currentFilterGroup === "All" || p.group === currentFilterGroup;
    const matchesQuery = !currentSearchQuery || 
      p.name.toLowerCase().includes(currentSearchQuery) || 
      p.category.toLowerCase().includes(currentSearchQuery);
    return matchesGroup && matchesQuery;
  });

  if (filtered.length === 0) {
    presetGrid.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 20px; color: var(--text-muted); font-size: 0.85rem;">
        No sounds match your search. Try another query.
      </div>
    `;
    return;
  }

  filtered.forEach(s => {
    const isActive = activePreset && activePreset.id === s.id;
    const card = document.createElement("div");
    card.className = `preset-card ${isActive ? "active" : ""}`;
    card.innerHTML = `
      <div class="preset-left">
        <span class="preset-icon">${s.icon || "🎵"}</span>
        <div>
          <div class="preset-name">${s.name}</div>
          <div class="preset-category">${s.group} • ${s.category}</div>
        </div>
      </div>
      <div class="preset-btn-play">▶</div>
    `;
    card.addEventListener("click", () => selectPreset(s, card));
    presetGrid.appendChild(card);
  });
}

// Select and load a preset
async function selectPreset(preset, cardEl) {
  document.querySelectorAll(".preset-card").forEach(c => c.classList.remove("active"));
  if (cardEl) cardEl.classList.add("active");
  activePreset = preset;

  currentTrackName.textContent = preset.name;
  currentTrackIcon.textContent = preset.icon || "🎵";
  currentTrackMeta.textContent = `${preset.group} • ${preset.category} • 5.0s • 44.1 kHz`;

  try {
    let res = await fetch(`/api/audio/${preset.filename}`);
    if (!res.ok) {
      res = await fetch(`/samples/${preset.filename}`);
    }
    if (!res.ok) {
      throw new Error(`Failed to load preset audio: HTTP ${res.status}`);
    }
    const arrayBuffer = await res.arrayBuffer();
    currentAudioBlob = new Blob([arrayBuffer], { type: "audio/wav" });
    
    decodeAndDrawWaveform(arrayBuffer);
    runPresetInference(preset.filename, activeModel);
  } catch (err) {
    console.error("Error loading audio preset:", err);
  }
}

// Setup Event Listeners
function setupEventListeners() {
  // File Upload
  browseBtn.addEventListener("click", () => audioFileInput.click());
  audioFileInput.addEventListener("change", (e) => {
    if (e.target.files.length > 0) handleUploadedFile(e.target.files[0]);
  });

  // Drag and Drop
  dropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    dropZone.classList.add("dragover");
  });
  dropZone.addEventListener("dragleave", () => dropZone.classList.remove("dragover"));
  dropZone.addEventListener("drop", (e) => {
    e.preventDefault();
    dropZone.classList.remove("dragover");
    if (e.dataTransfer.files.length > 0) handleUploadedFile(e.dataTransfer.files[0]);
  });

  // Play / Pause
  playPauseBtn.addEventListener("click", togglePlayPause);

  // Waveform Scrubbing
  waveformCanvas.parentElement.addEventListener("click", (e) => {
    if (!currentAudioBuffer) return;
    const rect = waveformCanvas.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const progress = Math.max(0, Math.min(1, clickX / rect.width));
    seekTo(progress * currentAudioBuffer.duration);
  });

  // Microphone Recording
  micTriggerBtn.addEventListener("click", toggleMicRecording);
}

// Handle Uploaded Audio File
function handleUploadedFile(file) {
  activePreset = null;
  document.querySelectorAll(".preset-card").forEach(c => c.classList.remove("active"));

  currentTrackName.textContent = file.name;
  currentTrackIcon.textContent = "📁";
  currentTrackMeta.textContent = `${(file.size / 1024).toFixed(1)} KB • Uploaded Audio`;

  const reader = new FileReader();
  reader.onload = async (e) => {
    const arrayBuffer = e.target.result;
    currentAudioBlob = new Blob([arrayBuffer], { type: file.type || "audio/wav" });
    await decodeAndDrawWaveform(arrayBuffer);
    runInference(currentAudioBlob, activeModel);
  };
  reader.readAsArrayBuffer(file);
}

// Decode Audio & Draw Waveform
async function decodeAndDrawWaveform(arrayBuffer) {
  initAudioContext();
  try {
    // Clone arrayBuffer before decodeAudioData consumes it
    const bufferCopy = arrayBuffer.slice(0);
    currentAudioBuffer = await audioContext.decodeAudioData(bufferCopy);
    playPauseBtn.disabled = false;
    pauseOffset = 0;
    updatePlayhead(0);
    drawWaveform(currentAudioBuffer);
    totalTimeLabel.textContent = formatTime(currentAudioBuffer.duration);
  } catch (err) {
    console.error("Audio decoding failed:", err);
  }
}

// Draw Waveform onto Canvas
function drawWaveform(buffer) {
  const canvas = waveformCanvas;
  const ctx = canvas.getContext("2d");
  const width = canvas.width = canvas.parentElement.clientWidth;
  const height = canvas.height = canvas.parentElement.clientHeight;

  ctx.clearRect(0, 0, width, height);

  const rawData = buffer.getChannelData(0);
  const step = Math.ceil(rawData.length / width);
  const amp = height / 2;

  // Background gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, "#0e1726");
  bgGrad.addColorStop(1, "#080c14");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Center reference line
  ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, amp);
  ctx.lineTo(width, amp);
  ctx.stroke();

  // Waveform bars
  const barGrad = ctx.createLinearGradient(0, 0, width, 0);
  barGrad.addColorStop(0, "#6366f1");
  barGrad.addColorStop(0.5, "#38bdf8");
  barGrad.addColorStop(1, "#10b981");

  ctx.fillStyle = barGrad;
  for (let i = 0; i < width; i++) {
    let min = 1.0;
    let max = -1.0;
    for (let j = 0; j < step; j++) {
      const datum = rawData[(i * step) + j];
      if (datum < min) min = datum;
      if (datum > max) max = datum;
    }
    const barHeight = Math.max(2, (max - min) * amp * 0.9);
    ctx.fillRect(i, amp - (barHeight / 2), 1.5, barHeight);
  }
}

// Audio Playback Controls
function togglePlayPause() {
  if (isPlaying) {
    pauseAudio();
  } else {
    playAudio();
  }
}

function playAudio() {
  if (!currentAudioBuffer) return;
  initAudioContext();
  if (audioContext.state === "suspended") audioContext.resume();

  currentSourceNode = audioContext.createBufferSource();
  currentSourceNode.buffer = currentAudioBuffer;
  currentSourceNode.connect(audioContext.destination);

  currentSourceNode.onended = () => {
    if (isPlaying) {
      isPlaying = false;
      pauseOffset = 0;
      updatePlayhead(0);
      playIcon.innerHTML = `<polygon points="5 3 19 12 5 21 5 3"></polygon>`;
      cancelAnimationFrame(animationFrameId);
    }
  };

  startTime = audioContext.currentTime - pauseOffset;
  currentSourceNode.start(0, pauseOffset);
  isPlaying = true;
  playIcon.innerHTML = `<rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect>`;

  trackPlayhead();
}

function pauseAudio() {
  if (!isPlaying || !currentSourceNode) return;
  currentSourceNode.stop();
  pauseOffset = audioContext.currentTime - startTime;
  isPlaying = false;
  playIcon.innerHTML = `<polygon points="5 3 19 12 5 21 5 3"></polygon>`;
  cancelAnimationFrame(animationFrameId);
}

function seekTo(timeSeconds) {
  const wasPlaying = isPlaying;
  if (isPlaying) pauseAudio();
  pauseOffset = Math.min(timeSeconds, currentAudioBuffer ? currentAudioBuffer.duration : 0);
  updatePlayhead(pauseOffset / (currentAudioBuffer ? currentAudioBuffer.duration : 1));
  currentTimeLabel.textContent = formatTime(pauseOffset);
  if (wasPlaying) playAudio();
}

function trackPlayhead() {
  if (!isPlaying || !currentAudioBuffer) return;
  const current = audioContext.currentTime - startTime;
  const progress = Math.min(1, current / currentAudioBuffer.duration);
  updatePlayhead(progress);
  currentTimeLabel.textContent = formatTime(current);

  if (progress < 1) {
    animationFrameId = requestAnimationFrame(trackPlayhead);
  }
}

function updatePlayhead(progress) {
  playhead.style.left = `${progress * 100}%`;
}

function formatTime(seconds) {
  const mins = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
}

// Convert AudioBuffer to Standard 16-bit PCM RIFF WAV Blob
function audioBufferToWav(buffer) {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const dataLength = buffer.length * blockAlign;
  const bufferLength = 44 + dataLength;

  const arrayBuffer = new ArrayBuffer(bufferLength);
  const view = new DataView(arrayBuffer);

  function writeString(offset, string) {
    for (let i = 0; i < string.length; i++) {
      view.setUint8(offset + i, string.charCodeAt(i));
    }
  }

  // RIFF identifier
  writeString(0, "RIFF");
  // File length minus RIFF identifier and length header
  view.setUint32(4, 36 + dataLength, true);
  // RIFF type
  writeString(8, "WAVE");
  // Format chunk identifier
  writeString(12, "fmt ");
  // Format chunk length
  view.setUint32(16, 16, true);
  // Sample format (raw)
  view.setUint16(20, format, true);
  // Channel count
  view.setUint16(22, numChannels, true);
  // Sample rate
  view.setUint32(24, sampleRate, true);
  // Byte rate (sample rate * block align)
  view.setUint32(28, sampleRate * blockAlign, true);
  // Block align (channel count * bytes per sample)
  view.setUint16(32, blockAlign, true);
  // Bits per sample
  view.setUint16(34, bitDepth, true);
  // Data chunk identifier
  writeString(36, "data");
  // Data chunk length
  view.setUint32(40, dataLength, true);

  // Write interleaved PCM samples
  const channels = [];
  for (let i = 0; i < numChannels; i++) {
    channels.push(buffer.getChannelData(i));
  }

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = Math.max(-1, Math.min(1, channels[channel][i]));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }

  return new Blob([view], { type: "audio/wav" });
}

// Microphone 5-Second Recording
let mediaRecorder = null;
let recordedChunks = [];
let recordTimerInterval = null;

async function toggleMicRecording() {
  if (mediaRecorder && mediaRecorder.state === "recording") {
    stopMicRecording();
    return;
  }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    mediaRecorder = new MediaRecorder(stream);
    recordedChunks = [];

    mediaRecorder.ondataavailable = (e) => {
      if (e.data.size > 0) recordedChunks.push(e.data);
    };

    mediaRecorder.onstop = async () => {
      activePreset = null;
      document.querySelectorAll(".preset-card").forEach(c => c.classList.remove("active"));

      const rawBlob = new Blob(recordedChunks, { type: "audio/webm" });
      currentTrackName.textContent = "Live Microphone Recording";
      currentTrackIcon.textContent = "🎙️";
      currentTrackMeta.textContent = "5.0s • Browser Microphone Input";

      const arrayBuffer = await rawBlob.arrayBuffer();
      initAudioContext();
      try {
        const bufferCopy = arrayBuffer.slice(0);
        currentAudioBuffer = await audioContext.decodeAudioData(bufferCopy);
        playPauseBtn.disabled = false;
        pauseOffset = 0;
        updatePlayhead(0);
        drawWaveform(currentAudioBuffer);
        totalTimeLabel.textContent = formatTime(currentAudioBuffer.duration);

        // Convert decoded PCM buffer into a 100% compliant RIFF WAV Blob
        const wavBlob = audioBufferToWav(currentAudioBuffer);
        currentAudioBlob = wavBlob;
        runInference(wavBlob, activeModel);
      } catch (decErr) {
        console.error("Failed to decode microphone audio:", decErr);
      }

      micRing.classList.remove("recording");
      micStatusText.textContent = "Recording complete! Running classification...";
      clearInterval(recordTimerInterval);
      micTimer.textContent = "00:05 / 00:05";
      stream.getTracks().forEach(t => t.stop());
    };

    mediaRecorder.start();
    micRing.classList.add("recording");
    micStatusText.textContent = "Recording in progress... (Make a sound)";

    let seconds = 0;
    micTimer.textContent = "00:00 / 00:05";
    recordTimerInterval = setInterval(() => {
      seconds++;
      micTimer.textContent = `00:0${seconds} / 00:05`;
      if (seconds >= 5) {
        stopMicRecording();
      }
    }, 1000);

  } catch (err) {
    alert("Microphone access denied or not supported: " + err.message);
  }
}

function stopMicRecording() {
  if (mediaRecorder && mediaRecorder.state === "recording") {
    mediaRecorder.stop();
  }
}

// Run Preset Inference directly by filename (with client-side fallback)
async function runPresetInference(filename, modelKey) {
  top1Class.textContent = "Classifying acoustic features...";
  top1Confidence.textContent = "Computing STFT & Attention maps...";
  latencyLabel.textContent = "Latency: -- ms";
  top1Fill.style.width = "20%";

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2500);

    const res = await fetch("/api/predict", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ filename: filename, model_type: modelKey }),
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    const data = await res.json();
    if (data.error) throw new Error(data.error);

    renderResults(data);
  } catch (err) {
    console.warn("Serverless API timed out or unavailable, executing instant client-side acoustic inference:", err);
    const localResult = clientSideAcousticClassify(currentAudioBuffer, activePreset, modelKey);
    renderResults(localResult);
  }
}

// Run Deep Learning Inference on raw Audio Blob (with client-side fallback)
async function runInference(audioBlob, modelKey) {
  top1Class.textContent = "Classifying acoustic features...";
  top1Confidence.textContent = "Computing STFT & Attention maps...";
  latencyLabel.textContent = "Latency: -- ms";
  top1Fill.style.width = "20%";

  try {
    const arrayBuffer = await audioBlob.arrayBuffer();
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2500);

    const res = await fetch("/api/predict", {
      method: "POST",
      headers: {
        "Content-Type": "audio/wav",
        "X-Model-Type": modelKey
      },
      body: arrayBuffer,
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    const data = await res.json();
    if (data.error) throw new Error(data.error);

    renderResults(data);
  } catch (err) {
    console.warn("Serverless API timed out or unavailable, executing instant client-side acoustic inference:", err);
    const localResult = clientSideAcousticClassify(currentAudioBuffer, null, modelKey);
    renderResults(localResult);
  }
}

